pub fn find_min(a: &[i32], lo: usize) -> usize {
    assert!(!a.is_empty(), "array must be non-empty");
    assert!(lo < a.len(), "lo must be within array bounds");

    let mut min_idx = lo;
    let mut min_val = a[lo];

    for i in (lo + 1)..a.len() {
        let v = a[i];
        if v < min_val {
            min_val = v;
            min_idx = i;
        }
    }

    min_idx
}

